-- Setup check: five row counts.
SELECT 'Customers' AS TableName, COUNT(*) AS RowsLoaded FROM Customers
UNION ALL
SELECT 'Products' AS TableName, COUNT(*) AS RowsLoaded FROM Products
UNION ALL
SELECT 'Orders' AS TableName, COUNT(*) AS RowsLoaded FROM Orders
UNION ALL
SELECT 'OrderItems' AS TableName, COUNT(*) AS RowsLoaded FROM OrderItems
UNION ALL
SELECT 'Deliveries' AS TableName, COUNT(*) AS RowsLoaded FROM Deliveries;

-- 1. Total sales excluding cancelled orders
SELECT
    SUM(i.Quantity * i.UnitPrice) AS GrossOrderSales
FROM Orders AS o
JOIN OrderItems AS i
    ON o.OrderID = i.OrderID
WHERE o.Status <> 'Cancelled';

-- 2. Total orders excluding cancelled orders
SELECT
    COUNT(*) AS TotalOrders
FROM Orders
WHERE Status <> 'Cancelled';

-- 3. Average order value
SELECT
    SUM(i.Quantity * i.UnitPrice) AS GrossOrderSales,
    COUNT(DISTINCT o.OrderID) AS TotalOrders,
    CAST(
        SUM(i.Quantity * i.UnitPrice)
        / COUNT(DISTINCT o.OrderID)
        AS DECIMAL(18, 2)
    ) AS AverageOrderValue
FROM Orders AS o
JOIN OrderItems AS i
    ON o.OrderID = i.OrderID
WHERE o.Status <> 'Cancelled';

-- 4. Monthly sales excluding cancelled orders
SELECT
    FORMAT(o.OrderDate, 'MMM') AS OrderMonth,
    SUM(i.Quantity * i.UnitPrice) AS MonthlySales
FROM Orders AS o
JOIN OrderItems AS i
    ON o.OrderID = i.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY
    MONTH(o.OrderDate),
    FORMAT(o.OrderDate, 'MMM')
ORDER BY MONTH(o.OrderDate);

-- 5. Sales by product
SELECT
    p.ProductName,
    SUM(i.Quantity * i.UnitPrice) AS ProductSales
FROM Products AS p
JOIN OrderItems AS i
    ON p.ProductID = i.ProductID
JOIN Orders AS o
    ON i.OrderID = o.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY p.ProductName
ORDER BY ProductSales DESC;

-- 6. Sales by region
SELECT
    c.Region,
    SUM(i.Quantity * i.UnitPrice) AS RegionSales
FROM Customers AS c
JOIN Orders AS o
    ON c.CustomerID = o.CustomerID
JOIN OrderItems AS i
    ON o.OrderID = i.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY c.Region
ORDER BY RegionSales DESC;

-- 7. Number of on-time deliveries
SELECT
    COUNT(*) AS OnTimeOrders
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.ActualDeliveryDate <= d.PromisedDeliveryDate;

-- 8. Delivered orders with both delivery dates available
SELECT
    COUNT(*) AS EligibleDeliveredOrders
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.ActualDeliveryDate IS NOT NULL
  AND d.PromisedDeliveryDate IS NOT NULL;

-- 9. Overall on-time delivery percentage
SELECT
    100.0 * AVG(
        CASE
            WHEN d.ActualDeliveryDate <= d.PromisedDeliveryDate
            THEN 1.0 ELSE 0.0
        END
    ) AS OnTimeDeliveryPercent
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.ActualDeliveryDate IS NOT NULL
  AND d.PromisedDeliveryDate IS NOT NULL;

-- 10. On-time delivery percentage by carrier
SELECT
    d.Carrier,
    100.0 * AVG(
        CASE
            WHEN d.ActualDeliveryDate <= d.PromisedDeliveryDate
            THEN 1.0 ELSE 0.0
        END
    ) AS OnTimeDeliveryPercent
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.ActualDeliveryDate IS NOT NULL
  AND d.PromisedDeliveryDate IS NOT NULL
GROUP BY d.Carrier
ORDER BY OnTimeDeliveryPercent DESC;

-- 11. Delivery percentage among orders dispatched on time
SELECT
    d.Carrier,
    100.0 * AVG(
        CASE
            WHEN d.ActualDeliveryDate <= d.PromisedDeliveryDate
            THEN 1.0 ELSE 0.0
        END
    ) AS OnTimeDeliveryPercent
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.ActualDeliveryDate IS NOT NULL
  AND d.PromisedDeliveryDate IS NOT NULL
  AND d.OrderDispatchDate <= d.PromisedDispatchDate
GROUP BY d.Carrier
ORDER BY OnTimeDeliveryPercent DESC;

-- 12. Number of delayed delivery status updates
SELECT
    COUNT(*) AS DelayedStatusUpdates
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.DeliveryStatusUpdateDate > d.ActualDeliveryDate;

-- 13. Percentage of delayed delivery status updates
SELECT
    100.0 * AVG(
        CASE
            WHEN d.DeliveryStatusUpdateDate > d.ActualDeliveryDate
            THEN 1.0 ELSE 0.0
        END
    ) AS DelayedStatusUpdatePercent
FROM Orders AS o
JOIN Deliveries AS d
    ON o.OrderID = d.OrderID
WHERE o.Status = 'Delivered'
  AND d.ActualDeliveryDate IS NOT NULL
  AND d.DeliveryStatusUpdateDate IS NOT NULL;

-- 14. Top five customers by sales
SELECT TOP 5
    c.CustomerID,
    c.CustomerName,
    SUM(i.Quantity * i.UnitPrice) AS CustomerSales,
    COUNT(DISTINCT o.OrderID) AS TotalOrders
FROM Customers AS c
JOIN Orders AS o
    ON c.CustomerID = o.CustomerID
JOIN OrderItems AS i
    ON o.OrderID = i.OrderID
WHERE o.Status <> 'Cancelled'
GROUP BY
    c.CustomerID,
    c.CustomerName
ORDER BY CustomerSales DESC, c.CustomerID;

-- 15. Product sales change from May to June
WITH ProductMonthlySales AS (
    SELECT
        p.ProductName,
        SUM(CASE
            WHEN MONTH(o.OrderDate) = 5
            THEN i.Quantity * i.UnitPrice ELSE 0
        END) AS MaySales,
        SUM(CASE
            WHEN MONTH(o.OrderDate) = 6
            THEN i.Quantity * i.UnitPrice ELSE 0
        END) AS JuneSales
    FROM Products AS p
    JOIN OrderItems AS i
        ON p.ProductID = i.ProductID
    JOIN Orders AS o
        ON i.OrderID = o.OrderID
    WHERE o.Status <> 'Cancelled'
    GROUP BY p.ProductName
)
SELECT
    ProductName,
    MaySales,
    JuneSales,
    JuneSales - MaySales AS SalesChange
FROM ProductMonthlySales
ORDER BY SalesChange DESC;
